WITH scored AS (SELECT *, FIRST_VALUE(duration_sec, TRUE) OVER (PARTITION BY event_type, session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_duration_sec, SUM(duration_sec) OVER (PARTITION BY event_type, session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec, MIN(duration_sec) OVER (PARTITION BY page) AS page_min_duration_sec FROM web_events), enriched AS (SELECT *, SUM(page_min_duration_sec) OVER (PARTITION BY event_type ORDER BY page_min_duration_sec ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_page_min_duration_sec, AVG(cumulative_duration_sec) OVER (PARTITION BY event_type ORDER BY CAST(event_time AS BIGINT) ASC RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS cumulative_duration_sec_avg_30d, LEAD(first_known_duration_sec, 1) OVER (PARTITION BY page ORDER BY cumulative_duration_sec ASC, id ASC) AS next_first_known_duration_sec FROM scored), flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM enriched), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT s.id, s.session_id, s.event_type, s.page, s.duration_sec, s.first_known_duration_sec, s.page_min_duration_sec, s.cumulative_duration_sec_avg_30d, s.next_first_known_duration_sec, (SELECT MIN(t2.duration_sec) FROM web_events t2 WHERE t2.session_id = s.session_id) AS min_web_event_duration_sec FROM islands s ORDER BY page DESC NULLS LAST;
